text:
{
 "title": "地方税法等の改正（令和6年度）",
 "lead": {
  "es": "令和《れいわ》6年度《ねんど》の住民税《じゅうみんぜい》の減税《げんぜい》など、都道府県《とどうふけん》や市町村《しちょうそん》の税《ぜい》のしくみを変《か》えた法律《ほうりつ》です。",
  "hs": "令和6年度の個人住民税の定額減税など、地方税のしくみを改めた法律です。",
  "std": "令和6年度分の個人住民税の定額減税、法人事業税の外形標準課税の見直しなど、地方税制を改正する法律です。",
  "univ": "個人住民税の定額減税の実施、法人事業税の外形標準課税の適用対象法人の見直し等を内容とする地方税法等の一部を改正する法律。"
 },
 "facts": [
  {
   "es": "令和《れいわ》6年度《ねんど》の住民税《じゅうみんぜい》を、決《き》まった額《がく》だけへらします（定額減税《ていがくげんぜい》）。",
   "hs": "令和6年度分の個人住民税について、定額減税を行う。",
   "std": "令和6年度分の個人住民税について、定額減税を実施します。",
   "univ": "令和6年度分の個人住民税について、定額減税を実施する。"
  },
  {
   "es": "会社《かいしゃ》にかかる税《ぜい》（法人事業税《ほうじんじぎょうぜい》）の一部《いちぶ》のしくみ（外形標準課税《がいけいひょうじゅんかぜい》）について、対象《たいしょう》の会社《かいしゃ》がへっていることなどから、対象《たいしょう》を見直《みなお》します。",
   "hs": "減資（資本金をへらすこと）などで法人事業税の外形標準課税の対象法人がへっていることなどに対応するため、対象法人を見直す。",
   "std": "減資等により外形標準課税の対象法人が減少していること等の課題に対応するため、法人事業税の外形標準課税の適用対象法人を見直します。",
   "univ": "減資等により外形標準課税の対象法人が減少していること等の課題に対応するため、法人事業税の外形標準課税の適用対象法人の見直しを行う。"
  },
  {
   "es": "土地《とち》や建物《たてもの》にかかる税《ぜい》（固定資産税《こていしさんぜい》・都市計画税《としけいかくぜい》）は、令和《れいわ》6年度《ねんど》の値打《ねう》ちの見直《みなお》しのときも、土地《とち》の税《ぜい》の負担《ふたん》を調整《ちょうせい》するしくみなどを続《つづ》けます。",
   "hs": "固定資産税と都市計画税は、令和6年度の｜評価替《ひょうかが》えにあたり、土地の負担調整｜措置《そち》などを続ける。",
   "std": "固定資産税・都市計画税について、令和6年度の評価替えに当たり、現行の土地に係る負担調整措置等を継続します。",
   "univ": "固定資産税及び都市計画税について、令和6年度の評価替えに当たり、現行の土地に係る負担調整措置等を継続する。"
  },
  {
   "es": "森林《しんりん》のための税《ぜい》のお金《かね》（森林環境譲与税《しんりんかんきょうじょうよぜい》）を分《わ》けるときのもとになる決《き》まりを見直《みなお》します。税《ぜい》を軽《かる》くするしくみなどを整理《せいり》します。",
   "hs": "森林｜環境《かんきょう》｜譲与《じょうよ》税の｜譲与《じょうよ》基準を見直す。税負担を軽くする｜措置《そち》などを整理・合理化する。",
   "std": "森林環境譲与税の譲与基準を見直します。税負担軽減措置等の整理合理化等を行います。",
   "univ": "森林環境譲与税について、譲与基準の見直しを行う。税負担軽減措置等の整理合理化等を行う。"
  },
  {
   "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞき、令和《れいわ》6年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。",
   "hs": "この法律は、一部をのぞき、令和6年4月1日から｜施行《しこう》する。",
   "std": "一部を除き、令和6年4月1日から施行します。",
   "univ": "この法律は、一部を除き、令和6年4月1日から施行する。"
  }
 ]
}
